declare(strict_types=1);

use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\FixtureFile;
use OCA\Mcp\Tests\Unit\Contract\NextcloudApi\SourceParser;

/**
 * Add the user_status surfaces the Status module names to the existing NC34/35 fixtures.
 * The sources are the hash-checked pins in tests/fixtures/user-status-native. IMapperException is copied only so the
 * mapper exception inherits Throwable, the same way the fixture already records DoesNotExistException; it is not rewritten.
 * Usage: php tests/fixtures/nextcloud-api/generate-user-status.php <34|35> [fixture output directory].
 * No network, source execution, server, SQL or unrelated fixture regeneration is involved.
 */
require __DIR__ . '/../../../vendor/autoload.php';
$major = $argv[1] ?? '';
$pins = json_decode((string)file_get_contents(__DIR__ . '/../user-status-native/sources.json'), true, 512, JSON_THROW_ON_ERROR)['versions'];
if (!isset($pins[$major])) {
	throw new RuntimeException('Expected a user status source pin: 34 or 35.');
}
$target = ($argv[2] ?? __DIR__) . '/' . $major . '.php';
/** Pin file => path inside the temporary server tree. */
$placed = [
	'UserStatus.php' => 'apps/user_status/lib/Db/UserStatus.php',
	'UserStatusMapper.php' => 'apps/user_status/lib/Db/UserStatusMapper.php',
	'MultipleObjectsReturnedException.php' => 'lib/public/AppFramework/Db/MultipleObjectsReturnedException.php',
	'IMapperException.php' => 'lib/public/AppFramework/Db/IMapperException.php',
];
$classes = [
	'OCA\\UserStatus\\Db\\UserStatus',
	'OCA\\UserStatus\\Db\\UserStatusMapper',
	'OCP\\AppFramework\\Db\\MultipleObjectsReturnedException',
];
$tree = sys_get_temp_dir() . '/mcp-user-status-api-' . bin2hex(random_bytes(6));
try {
	foreach ($placed as $file => $destination) {
		$source = __DIR__ . '/../user-status-native/' . $major . '/' . $file;
		if (!isset($pins[$major][$file]['sha256']) || hash_file('sha256', $source) !== $pins[$major][$file]['sha256']) {
			throw new RuntimeException('User status source SHA256 mismatch: ' . $file);
		}
		@mkdir($tree . '/' . dirname($destination), recursive: true);
		copy($source, $tree . '/' . $destination);
	}
	$fixture = require $target;
	$parser = new SourceParser($tree);
	foreach ($classes as $class) {
		$surface = $parser->surface($class);
		if ($surface === null) {
			throw new RuntimeException('Missing pinned user status surface: ' . $class);
		}
		$fixture['classes'][$class] = $surface;
	}
	ksort($fixture['classes']);
	$original = (string)file_get_contents($target);
	$header = substr($original, 0, (int)strpos($original, 'return ['));
	$header = (string)preg_replace('~// User status surfaces generated[^\n]*\n~', '', $header);
	$header .= "// User status surfaces generated by generate-user-status.php; exact source URLs and SHAs in user-status-native/sources.json.\n";
	FixtureFile::write($target, $header, $fixture);
	echo 'Generated user status surfaces for NC' . $major . "\n";
} finally {
	if (is_dir($tree)) {
		$files = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($tree, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::CHILD_FIRST);
		foreach ($files as $file) {
			$file->isDir() ? rmdir($file->getPathname()) : unlink($file->getPathname());
		}
		rmdir($tree);
	}
}
